mapper.select:
select tmp.finprodId, SUM(tmp.AMOUNT) as amount FROM ( SELECT CASE
WHEN A.FINPROD_ID=#{item} THEN #{item}
ELSE #{finprodId_qt} END AS finprodId, IFNULL(B.AMOUNT,0) AS amount FROM FIN_PRODUCT_ADD A INNER JOIN PTL_CASH_POSITION B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID AND B.CDATE = #{queryDate}-1 AND B.HODING_TYPE = #{holdingType} WHERE 1=1
AND A.FINPROD_ID IN
null) OR A.FINPROD_ID in (
#{item}
) tmp GROUP BY tmp.finprodId

SELECT tmp.finprodId, tmp.type, SUM(tmp.amount) as amount FROM ( SELECT CASE
WHEN A.FINPROD_ID=#{item} THEN #{item}
ELSE #{finprodId_qt} END AS finprodId, (CASE WHEN C.FINPROD_TYPE2 = #{finprodType2_1} THEN #{finprodTypeRepoN} WHEN #{finprodType2_2} THEN #{finprodTypeRepoN} WHEN #{finprodType2_3} THEN #{finprodTypeRepo} WHEN #{finprodType2_4} THEN #{finprodTypeRepo} END) as type,
IFNULL(B.AMOUNT,0) AS amount FROM FIN_PRODUCT_ADD A INNER JOIN PTL_SEC_POSITION B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID AND B.CDATE = #{queryDate}-1 AND B.HODING_TYPE = #{holdingType} INNER JOIN FIN_TRADE_PRODUCT C ON B.FINPROD_ID = C.FINPROD_ID AND B.BRANCH = C.BRANCH AND C.FINPROD_TYPE2 IN (#{finprodType2_1},#{finprodType2_2},#{finprodType2_3},#{finprodType2_4}) WHERE 1=1
AND A.FINPROD_ID IN
null) OR A.FINPROD_ID in (
#{item}
) tmp GROUP BY tmp.finprodId,tmp.type ORDER BY tmp.type,tmp.finprodId

SELECT S.finprodId, S.type, S.holdingType, S.amount*S.faceValue as amount FROM ( SELECT tmp.finprodId, tmp.type, tmp.holdingType, SUM(tmp.AMOUNT) as amount, tmp.faceValue FROM ( SELECT CASE
WHEN A.FINPROD_ID=#{item} THEN #{item}
ELSE #{finprodId_qt} END AS finprodId, B.HODING_TYPE AS holdingType, B.AMOUNT as amount, ( SELECT 100-IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE <= B.CDATE ) AS faceValue,
CASE
WHEN D.TYPE_6 = #{secType1_GZ} THEN #{secType1_GZ}
WHEN D.TYPE_6 = #{secType1_TYCD} THEN #{secType1_TYCD}
WHEN D.TYPE_6=#{secType1_JRZ} AND D.TYPE_7=#{secType2_ZCYHZ} THEN #{secType1_JRZ} ELSE NULL END AS type FROM FIN_PRODUCT_ADD A INNER JOIN PTL_SEC_POSITION B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID AND B.CDATE = #{queryDate}-1 AND B.HODING_TYPE in (#{holdingType_SJ},#{holdingType_ZY}) INNER JOIN FIN_PRODUCT C ON B.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 =#{finprodType2} INNER JOIN FIN_PRODUCT_TYPE D ON D.FINPROD_ID = C.FINPROD_ID AND (D.TYPE_6 IN (#{secType1_GZ},#{secType1_TYCD}) OR (D.TYPE_6=#{secType1_JRZ} AND D.TYPE_7=#{secType2_ZCYHZ})) WHERE 1=1
AND A.FINPROD_ID IN
null) OR A.FINPROD_ID in (
#{item}
) tmp GROUP BY tmp.finprodId, tmp.type, tmp.holdingType,tmp.faceValue ) S

SELECT tmp.type, tmp.holdingType, SUM(tmp.AMOUNT*tmp.faceValue1) as targetTimeone, SUM(tmp.AMOUNT*tmp.faceValue2) as targetTimetwo, SUM(tmp.AMOUNT*tmp.faceValue3) as targetTimethree, SUM(tmp.AMOUNT*tmp.faceValue4) as targetTimefour, SUM(tmp.AMOUNT*tmp.faceValue5) as targetTimefive, SUM(tmp.AMOUNT*tmp.faceValue6) as targetTimesix FROM ( SELECT C.FINPROD_TYPE2 AS type, B.HODING_TYPE AS holdingType, B.AMOUNT as amount, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area1BeginDate} and #{area1EndDate} ) AS faceValue1, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area2BeginDate} and #{area2EndDate} ) AS faceValue2, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area3BeginDate} and #{area3EndDate} ) AS faceValue3, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area4BeginDate} and #{area4EndDate} ) AS faceValue4, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area5BeginDate} and #{area5EndDate} ) AS faceValue5, ( SELECT IFNULL(SUM(Y.PRIN_AMT),0) FROM FIN_CASH_INFO X INNER JOIN FIN_CASH_PLAN Y ON X.CASH_ID = Y.CASH_ID AND X.CASH_TYPE_1 = #{cashType1} WHERE X.FINPROD_ID = C.FINPROD_ID AND X.FINPROD_TYPE= #{finprodType} AND Y.MDATE BETWEEN #{area6BeginDate} and #{area6EndDate} ) AS faceValue6 FROM FIN_PRODUCT_ADD A INNER JOIN PTL_SEC_POSITION B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID AND B.CDATE = #{queryDate}-1 AND B.HODING_TYPE = #{holdingType_SJ} INNER JOIN FIN_PRODUCT C ON B.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 =#{finprodType2} WHERE 1=1
AND A.FINPROD_ID IN
null) OR A.FINPROD_ID in (
#{item}
) tmp GROUP BY tmp.type, tmp.holdingType

SELECT tmp.type, tmp.dateArea, tmp.areaIndex, SUM(tmp.AMOUNT) as amount FROM ( SELECT (CASE
WHEN C.INVESTOR_TYPE like concat_ws('','%', #{invType_GR_1} , '%') OR C.INVESTOR_TYPE like concat_ws('','%' , #{invType_GR_2}, '%' ) OR C.INVESTOR_TYPE like concat_ws('','%' , #{invType_GR_3} , '%' ) THEN #{invType_GR}
WHEN C.INVESTOR_TYPE like concat_ws('','%' , #{invType_JG_1} , '%') OR C.INVESTOR_TYPE like concat_ws('','%', #{invType_JG_2},'%') THEN #{invType_JG} ELSE '0' END) AS type, (CASE WHEN B.MDATE BETWEEN #{area1BeginDate} AND #{area1EndDate} THEN #{area1} WHEN B.MDATE BETWEEN #{area2BeginDate} AND #{area2EndDate} THEN #{area2} WHEN B.MDATE BETWEEN #{area3BeginDate} AND #{area3EndDate} THEN #{area3} WHEN B.MDATE BETWEEN #{area4BeginDate} AND #{area4EndDate} THEN #{area4} WHEN B.MDATE BETWEEN #{area5BeginDate} AND #{area5EndDate} THEN #{area5} WHEN B.MDATE BETWEEN #{area6BeginDate} AND #{area6EndDate} THEN #{area6} ELSE '0' END) AS dateArea, (CASE WHEN B.MDATE BETWEEN #{area1BeginDate} AND #{area1EndDate} THEN '01' WHEN B.MDATE BETWEEN #{area2BeginDate} AND #{area2EndDate} THEN '02' WHEN B.MDATE BETWEEN #{area3BeginDate} AND #{area3EndDate} THEN '03' WHEN B.MDATE BETWEEN #{area4BeginDate} AND #{area4EndDate} THEN '04' WHEN B.MDATE BETWEEN #{area5BeginDate} AND #{area5EndDate} THEN '05' WHEN B.MDATE BETWEEN #{area6BeginDate} AND #{area6EndDate} THEN '06' ELSE '0' END) AS areaIndex, A.TDY_SHARE_AMT as amount
FROM BOK_POSITION_PRD A INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.MDATE BETWEEN #{area1BeginDate} and #{area6EndDate} AND B.OPERATION_TYPE = #{operationType} INNER JOIN PRD_SALE_PARAM C ON A.FINPROD_ID = C.FINPROD_ID WHERE A.BRANCH = 0 AND A.CDATE = #{queryDate}-1 AND 1=1
AND A.FINPROD_ID IN
null) OR A.FINPROD_ID in (
#{item}
) tmp GROUP BY tmp.type, tmp.dateArea,tmp.areaIndex ORDER BY tmp.type,tmp.dateArea,tmp.areaIndex
